  { "name": "cb.hready (sampled #1step)", "wave": "0..1." },
  { "name": "TB writes cb.haddr",   "wave": "x=...", "data": ["A1"] },
  { "name": "haddr on pins (output #1)", "wave": "x.=..", "data": ["A1"] }
],
  "head": { "text": "inputs: value just before the edge; outputs: applied a skew after the edge" } }
